-- Dr. Rodas Foundation — Museum Fundraising Platform — MySQL 8 schema (design source of truth)
-- Laravel migrations in apps/api/database/migrations mirror this file. Amounts DECIMAL(15,2), never FLOAT.
-- Museum designations only: preservation, exhibitions, education, collections, community, research, capital, general.

CREATE TABLE currencies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code CHAR(3) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, symbol VARCHAR(8) NULL, is_reporting TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE exchange_rates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, from_currency_id BIGINT UNSIGNED NOT NULL, to_currency_id BIGINT UNSIGNED NOT NULL, rate DECIMAL(18,8) NOT NULL, effective_date DATE NOT NULL, source VARCHAR(120) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_xr_from FOREIGN KEY (from_currency_id) REFERENCES currencies(id), CONSTRAINT fk_xr_to FOREIGN KEY (to_currency_id) REFERENCES currencies(id));
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, description VARCHAR(255) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (role_id, permission_id), CONSTRAINT fk_rp_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE, CONSTRAINT fk_rp_perm FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
-- users is created by Laravel's base migration (id, name, email UNIQUE, password, remember_token, timestamps) + status column added by RBAC migration.
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (user_id, role_id), CONSTRAINT fk_ur_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_ur_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE donor_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL UNIQUE, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NULL, phone VARCHAR(40) NULL, country VARCHAR(80) NULL, public_recognition TINYINT(1) NOT NULL DEFAULT 0, marketing_opt_in TINYINT(1) NOT NULL DEFAULT 0, updates_opt_in TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_dp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE campaign_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, slug VARCHAR(160) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, summary VARCHAR(500) NULL, description LONGTEXT NULL, purpose VARCHAR(200) NULL, target_amount DECIMAL(15,2) NOT NULL DEFAULT 0, currency_id BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', starts_at DATE NULL, deadline DATE NULL, manager_id BIGINT UNSIGNED NULL, is_featured TINYINT(1) NOT NULL DEFAULT 0, cover_image_url VARCHAR(500) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX idx_campaigns_status (status), CONSTRAINT fk_c_cat FOREIGN KEY (category_id) REFERENCES campaign_categories(id) ON DELETE SET NULL, CONSTRAINT fk_c_cur FOREIGN KEY (currency_id) REFERENCES currencies(id), CONSTRAINT fk_c_mgr FOREIGN KEY (manager_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE campaign_media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campaign_id BIGINT UNSIGNED NOT NULL, url VARCHAR(500) NOT NULL, caption VARCHAR(255) NULL, media_type VARCHAR(20) NOT NULL DEFAULT 'image', sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_cm_c FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE);
CREATE TABLE campaign_updates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campaign_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NULL, title VARCHAR(200) NOT NULL, body LONGTEXT NOT NULL, is_published TINYINT(1) NOT NULL DEFAULT 0, published_at TIMESTAMP NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_cu_c FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE, CONSTRAINT fk_cu_a FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE programs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campaign_id BIGINT UNSIGNED NULL, name VARCHAR(200) NOT NULL, description TEXT NULL, beneficiary_description TEXT NULL, eligibility TEXT NULL, location VARCHAR(160) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_p_c FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE SET NULL);
CREATE TABLE payment_providers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, methods JSON NULL, mode VARCHAR(10) NOT NULL DEFAULT 'test', is_enabled TINYINT(1) NOT NULL DEFAULT 0, config JSON NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE donations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, campaign_id BIGINT UNSIGNED NOT NULL, donor_profile_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, designation VARCHAR(40) NOT NULL DEFAULT 'general', donation_type VARCHAR(20) NOT NULL DEFAULT 'one_time', amount DECIMAL(15,2) NOT NULL, currency_id BIGINT UNSIGNED NOT NULL, reporting_amount DECIMAL(15,2) NULL, exchange_rate_id BIGINT UNSIGNED NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', is_anonymous TINYINT(1) NOT NULL DEFAULT 0, donor_name VARCHAR(160) NULL, donor_email VARCHAR(190) NULL, donor_country VARCHAR(80) NULL, message TEXT NULL, message_is_public TINYINT(1) NOT NULL DEFAULT 0, idempotency_key VARCHAR(80) NULL UNIQUE, confirmed_at TIMESTAMP NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX idx_don_campaign_status (campaign_id, status), CONSTRAINT fk_d_c FOREIGN KEY (campaign_id) REFERENCES campaigns(id), CONSTRAINT fk_d_dp FOREIGN KEY (donor_profile_id) REFERENCES donor_profiles(id) ON DELETE SET NULL, CONSTRAINT fk_d_u FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_d_cur FOREIGN KEY (currency_id) REFERENCES currencies(id));
CREATE TABLE donation_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, donation_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NULL, category_slug VARCHAR(60) NOT NULL, amount DECIMAL(15,2) NOT NULL, notes VARCHAR(255) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_da_d FOREIGN KEY (donation_id) REFERENCES donations(id) ON DELETE CASCADE, CONSTRAINT fk_da_p FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE SET NULL);
CREATE TABLE payment_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, donation_id BIGINT UNSIGNED NOT NULL, payment_provider_id BIGINT UNSIGNED NOT NULL, provider_reference VARCHAR(120) NULL, method VARCHAR(40) NOT NULL, amount DECIMAL(15,2) NOT NULL, currency_id BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'initiated', fee_amount DECIMAL(15,2) NOT NULL DEFAULT 0, net_amount DECIMAL(15,2) NULL, authorized_at TIMESTAMP NULL, captured_at TIMESTAMP NULL, settled_at TIMESTAMP NULL, raw_payload JSON NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX idx_pt_provider_ref (provider_reference), CONSTRAINT fk_pt_d FOREIGN KEY (donation_id) REFERENCES donations(id) ON DELETE CASCADE, CONSTRAINT fk_pt_pp FOREIGN KEY (payment_provider_id) REFERENCES payment_providers(id), CONSTRAINT fk_pt_cur FOREIGN KEY (currency_id) REFERENCES currencies(id));
CREATE TABLE payment_webhook_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_provider_id BIGINT UNSIGNED NOT NULL, provider_event_id VARCHAR(160) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSON NOT NULL, signature_valid TINYINT(1) NOT NULL DEFAULT 0, processed_at TIMESTAMP NULL, processing_error TEXT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, UNIQUE KEY uq_webhook_event (payment_provider_id, provider_event_id), CONSTRAINT fk_we_pp FOREIGN KEY (payment_provider_id) REFERENCES payment_providers(id) ON DELETE CASCADE);
CREATE TABLE refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, donation_id BIGINT UNSIGNED NOT NULL, payment_transaction_id BIGINT UNSIGNED NULL, amount DECIMAL(15,2) NOT NULL, reason VARCHAR(255) NULL, status VARCHAR(30) NOT NULL DEFAULT 'requested', requested_by BIGINT UNSIGNED NULL, approved_by BIGINT UNSIGNED NULL, processed_at TIMESTAMP NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_r_d FOREIGN KEY (donation_id) REFERENCES donations(id), CONSTRAINT fk_r_pt FOREIGN KEY (payment_transaction_id) REFERENCES payment_transactions(id) ON DELETE SET NULL);
CREATE TABLE recurring_donations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, donation_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, campaign_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(15,2) NOT NULL, currency_id BIGINT UNSIGNED NOT NULL, frequency VARCHAR(20) NOT NULL DEFAULT 'monthly', status VARCHAR(30) NOT NULL DEFAULT 'pending_gateway', provider_subscription_ref VARCHAR(160) NULL, next_charge_at DATE NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_rd_c FOREIGN KEY (campaign_id) REFERENCES campaigns(id), CONSTRAINT fk_rd_cur FOREIGN KEY (currency_id) REFERENCES currencies(id));
CREATE TABLE donation_receipts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, donation_id BIGINT UNSIGNED NOT NULL UNIQUE, receipt_number VARCHAR(40) NOT NULL UNIQUE, issued_at TIMESTAMP NULL, pdf_path VARCHAR(500) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_dr_d FOREIGN KEY (donation_id) REFERENCES donations(id) ON DELETE CASCADE);
CREATE TABLE fund_disbursements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campaign_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NULL, amount DECIMAL(15,2) NOT NULL, currency_id BIGINT UNSIGNED NOT NULL, purpose VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending_approval', prepared_by BIGINT UNSIGNED NULL, approved_by BIGINT UNSIGNED NULL, disbursed_at TIMESTAMP NULL, supporting_document_url VARCHAR(500) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_fd_c FOREIGN KEY (campaign_id) REFERENCES campaigns(id), CONSTRAINT fk_fd_cur FOREIGN KEY (currency_id) REFERENCES currencies(id));
CREATE TABLE financial_approvals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, approvable_type VARCHAR(120) NOT NULL, approvable_id BIGINT UNSIGNED NOT NULL, approver_id BIGINT UNSIGNED NULL, decision VARCHAR(20) NOT NULL, notes TEXT NULL, decided_at TIMESTAMP NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX idx_fa_morph (approvable_type, approvable_id));
CREATE TABLE notification_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, email VARCHAR(190) NULL, channel VARCHAR(20) NOT NULL DEFAULT 'email', template VARCHAR(80) NOT NULL, subject VARCHAR(255) NULL, status VARCHAR(20) NOT NULL DEFAULT 'queued', sent_at TIMESTAMP NULL, failure_reason TEXT NULL, dedupe_key VARCHAR(120) NULL UNIQUE, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(120) NOT NULL, auditable_type VARCHAR(120) NULL, auditable_id BIGINT UNSIGNED NULL, old_values JSON NULL, new_values JSON NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX idx_al_morph (auditable_type, auditable_id));
CREATE TABLE system_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(120) NOT NULL UNIQUE, value TEXT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
